omniwrap_client <- function(base_url, bearer_token = NULL, api_key = NULL,
                            api_key_header = "X-API-Key", basic_username = NULL,
                            basic_password = NULL, oauth_provider = NULL,
                            connect_timeout = 10L, timeout = 60L, max_retries = 0L,
                            idempotency_key = NULL, hooks = NULL) {
  if (!is.character(base_url) || length(base_url) != 1L || is.na(base_url) ||
      !grepl("^https?://[^/?#[:space:]]+(/[^?#[:space:]]*)?$", base_url)) {
    stop("base_url must be an HTTP or HTTPS origin with an optional path")
  }
  if (!is.null(bearer_token) && (!is.character(bearer_token) || length(bearer_token) != 1L ||
      is.na(bearer_token) || grepl("[\r\n]", bearer_token))) stop("Invalid bearer token")
  if (!is.null(api_key) && (!is.character(api_key) || length(api_key) != 1L ||
      is.na(api_key) || grepl("[\r\n]", api_key))) stop("Invalid API key")
  if (!is.null(idempotency_key) && (!is.character(idempotency_key) || length(idempotency_key) != 1L ||
      is.na(idempotency_key) || grepl("[\r\n]", idempotency_key))) stop("Invalid idempotency key")
  structure(list(
    base_url = sub("/+$", "", base_url),
    bearer_token = bearer_token,
    api_key = api_key,
    api_key_header = api_key_header,
    basic_username = basic_username,
    basic_password = basic_password,
    oauth_provider = oauth_provider,
    connect_timeout = as.integer(connect_timeout),
    timeout = as.integer(timeout),
    max_retries = max(0L, as.integer(max_retries)),
    idempotency_key = idempotency_key,
    hooks = hooks
  ), class = "omniwrap_client")
}

omniwrap_request_hooks <- function(before_request = NULL, after_response = NULL, on_error = NULL) {
  structure(list(before_request = before_request, after_response = after_response, on_error = on_error),
            class = "omniwrap_request_hooks")
}

omniwrap_oauth_provider <- function(token_url, client_id, client_secret, scopes = character(),
                                    refresh_margin_seconds = 60, clock = function() as.numeric(Sys.time()),
                                    transport = NULL) {
  env <- new.env(parent = emptyenv())
  env$token_url <- token_url
  env$client_id <- client_id
  env$client_secret <- client_secret
  env$scopes <- scopes
  env$refresh_margin_seconds <- refresh_margin_seconds
  env$clock <- clock
  env$transport <- transport
  env$cached_token <- NULL
  env$expires_at <- 0
  class(env) <- "omniwrap_oauth_provider"
  env
}

omniwrap_oauth_access_token <- function(provider, force_refresh = FALSE) {
  now <- as.numeric(provider$clock())
  if (!isTRUE(force_refresh) && !is.null(provider$cached_token) &&
      (now + provider$refresh_margin_seconds) < provider$expires_at) {
    return(provider$cached_token)
  }
  fields <- c(
    paste0("grant_type=client_credentials"),
    paste0("client_id=", ow_escape(provider$client_id)),
    paste0("client_secret=", ow_escape(provider$client_secret))
  )
  if (length(provider$scopes)) {
    fields <- c(fields, paste0("scope=", ow_escape(paste(provider$scopes, collapse = " "))))
  }
  payload <- paste(fields, collapse = "&")
  if (is.function(provider$transport)) {
    resp <- provider$transport(provider$token_url, payload)
  } else {
    handle <- curl::new_handle()
    curl::handle_setheaders(handle, "Content-Type" = "application/x-www-form-urlencoded", Accept = "application/json")
    curl::handle_setopt(handle, postfields = payload, connecttimeout = 10L, timeout = 30L)
    raw_resp <- curl::curl_fetch_memory(provider$token_url, handle = handle)
    resp <- list(status = raw_resp$status_code, body = rawToChar(raw_resp$content))
  }
  if (is.null(resp$status) || resp$status < 200L || resp$status >= 300L) {
    stop(sprintf("OAuth token request failed (status=%s): [redacted]", as.character(resp$status)))
  }
  parsed <- jsonlite::fromJSON(resp$body, simplifyVector = TRUE)
  if (is.null(parsed$access_token) || !nzchar(parsed$access_token)) {
    stop("OAuth response missing access_token: [redacted]")
  }
  ttl <- if (!is.null(parsed$expires_in) && is.numeric(parsed$expires_in) && parsed$expires_in > 0) as.numeric(parsed$expires_in) else 3600
  provider$cached_token <- as.character(parsed$access_token)
  provider$expires_at <- now + ttl
  provider$cached_token
}

omniwrap_api_error <- function(status_code, method, path, body, request_id = NULL) {
  structure(
    list(message = sprintf("HTTP %d on %s %s", as.integer(status_code), method, path),
         status_code = as.integer(status_code), method = method, path = path,
         body = body, request_id = request_id,
         retryable = as.integer(status_code) %in% c(408L, 429L) || as.integer(status_code) >= 500L),
    class = c("omniwrap_api_error", "error", "condition")
  )
}

omniwrap_page_envelope <- function(items, has_more = FALSE, next_cursor = NULL, next_offset = NULL, status = 200L) {
  structure(list(items = items, has_more = isTRUE(has_more), next_cursor = next_cursor,
                 next_offset = next_offset, status = as.integer(status)),
            class = "omniwrap_page")
}

omniwrap_parse_sse_lines <- function(lines) {
  events <- list()
  cur <- list(event = "message", data = character(), id = NULL, retry = NULL)
  has_fields <- FALSE
  for (line in lines) {
    if (!nzchar(line)) {
      if (has_fields) {
        events[[length(events) + 1L]] <- list(event = cur$event, data = paste(cur$data, collapse = "\n"),
                                              id = cur$id, retry = cur$retry)
        cur <- list(event = "message", data = character(), id = NULL, retry = NULL)
        has_fields <- FALSE
      }
      next
    }
    if (startsWith(line, "event:")) { cur$event <- trimws(substring(line, 7L)); has_fields <- TRUE }
    else if (startsWith(line, "data:")) { cur$data <- c(cur$data, sub("^ ", "", substring(line, 6L))); has_fields <- TRUE }
    else if (startsWith(line, "id:")) { cur$id <- trimws(substring(line, 4L)); has_fields <- TRUE }
    else if (startsWith(line, "retry:")) { cur$retry <- suppressWarnings(as.integer(trimws(substring(line, 7L)))); has_fields <- TRUE }
  }
  if (has_fields) {
    events[[length(events) + 1L]] <- list(event = cur$event, data = paste(cur$data, collapse = "\n"),
                                          id = cur$id, retry = cur$retry)
  }
  events
}

omniwrap_parse_ndjson_lines <- function(text) {
  raw_lines <- strsplit(text, "\r?\n", perl = TRUE)[[1L]]
  non_empty <- raw_lines[nzchar(trimws(raw_lines))]
  lapply(non_empty, function(line) jsonlite::fromJSON(line, simplifyVector = FALSE))
}

omniwrap_websocket_url <- function(base_url, path) {
  trimmed <- sub("/+$", "", base_url)
  ws_base <- sub("^https://", "wss://", sub("^http://", "ws://", trimmed))
  sep <- if (startsWith(path, "/")) "" else "/"
  paste0(ws_base, sep, path)
}

omniwrap_websocket_backoff_ms <- function(attempt, base_ms = 250, max_ms = 30000) {
  min(as.numeric(max_ms), as.numeric(base_ms) * (2 ^ max(0, as.numeric(attempt))))
}

ow_base64 <- function(raw_bytes) {
  alphabet <- strsplit("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/", "")[[1L]]
  n <- length(raw_bytes)
  if (!n) return("")
  ints <- as.integer(raw_bytes)
  out <- character()
  i <- 1L
  while (i <= n) {
    b0 <- ints[i]
    b1 <- if (i + 1L <= n) ints[i + 1L] else 0L
    b2 <- if (i + 2L <= n) ints[i + 2L] else 0L
    v <- b0 * 65536 + b1 * 256 + b2
    c1 <- alphabet[(v %/% 262144) + 1L]
    c2 <- alphabet[((v %/% 4096) %% 64) + 1L]
    c3 <- if (i + 1L <= n) alphabet[((v %/% 64) %% 64) + 1L] else "="
    c4 <- if (i + 2L <= n) alphabet[(v %% 64) + 1L] else "="
    out <- c(out, paste0(c1, c2, c3, c4))
    i <- i + 3L
  }
  paste(out, collapse = "")
}

ow_u32 <- function(x) {
  m <- x %% 4294967296
  ifelse(m < 0, m + 4294967296, m)
}

ow_bit_op <- function(a, b, op) {
  a <- ow_u32(a); b <- ow_u32(b)
  res <- 0; mult <- 1
  for (i in 1L:32L) {
    ba <- a %% 2; bb <- b %% 2
    bit <- if (op == "and") ba * bb else if (op == "xor") (ba + bb) %% 2 else 1 - ba
    if (bit == 1) res <- res + mult
    a <- floor(a / 2); b <- floor(b / 2); mult <- mult * 2
  }
  res
}

ow_rotr32 <- function(x, n) {
  x <- ow_u32(x)
  ow_u32(floor(x / (2 ^ n)) + ((x %% (2 ^ n)) * (2 ^ (32 - n))))
}

ow_sha256_raw <- function(msg_raw) {
  k <- c(
    1116352408,1899447441,3049323471,3921009573,961987163,1508970993,2453635748,2870763221,
    3624381080,310598401,607225278,1426881987,1925078388,2162078206,2614888103,3248222580,
    3835390401,4022224774,264347078,604807628,770255983,1249150122,1555081692,1996064986,
    2554220882,2821834349,2952996808,3210313671,3336571891,3584528711,113926993,338241895,
    666307205,773529912,1294757372,1396182291,1695183700,1986661051,2177026350,2456956037,
    2730485921,2820302411,3259730800,3345764771,3516065817,3600352804,4094571909,275423344,
    430227734,506948616,659060556,883997877,958139571,1322822218,1537002063,1747873779,
    1955562222,2024104815,2227730452,2361852424,2428436474,2756734187,3204031479,3329325298
  )
  h <- c(1779033703,3144134277,1013904242,2773480762,1359893119,2600822924,528734635,1541459225)
  n <- length(msg_raw)
  pad_len <- (56L - ((n + 1L) %% 64L)) %% 64L
  bits <- as.numeric(n) * 8
  len_bytes <- as.raw(vapply(7L:0L, function(i) as.integer(floor(bits / (2 ^ (i * 8))) %% 256), integer(1)))
  padded <- c(msg_raw, as.raw(0x80), raw(pad_len), len_bytes)
  blocks <- length(padded) %/% 64L
  for (blk in seq_len(blocks)) {
    off <- (blk - 1L) * 64L
    w <- numeric(64L)
    for (i in 1L:16L) {
      j <- off + (i - 1L) * 4L
      w[i] <- as.integer(padded[j+1L])*16777216 + as.integer(padded[j+2L])*65536 +
              as.integer(padded[j+3L])*256 + as.integer(padded[j+4L])
    }
    for (i in 17L:64L) {
      s0 <- ow_bit_op(ow_bit_op(ow_rotr32(w[i-15L], 7), ow_rotr32(w[i-15L], 18), "xor"), floor(w[i-15L] / 8), "xor")
      s1 <- ow_bit_op(ow_bit_op(ow_rotr32(w[i-2L], 17), ow_rotr32(w[i-2L], 19), "xor"), floor(w[i-2L] / 1024), "xor")
      w[i] <- ow_u32(w[i-16L] + s0 + w[i-7L] + s1)
    }
    a<-h[1]; b<-h[2]; c<-h[3]; d<-h[4]; e<-h[5]; f<-h[6]; g<-h[7]; hh<-h[8]
    for (i in 1L:64L) {
      S1 <- ow_bit_op(ow_bit_op(ow_rotr32(e, 6), ow_rotr32(e, 11), "xor"), ow_rotr32(e, 25), "xor")
      ch <- ow_bit_op(ow_bit_op(e, f, "and"), ow_bit_op(ow_bit_op(e, 0, "not"), g, "and"), "xor")
      t1 <- ow_u32(hh + S1 + ch + k[i] + w[i])
      S0 <- ow_bit_op(ow_bit_op(ow_rotr32(a, 2), ow_rotr32(a, 13), "xor"), ow_rotr32(a, 22), "xor")
      maj <- ow_bit_op(ow_bit_op(ow_bit_op(a, b, "and"), ow_bit_op(a, c, "and"), "xor"), ow_bit_op(b, c, "and"), "xor")
      t2 <- ow_u32(S0 + maj)
      hh<-g; g<-f; f<-e; e<-ow_u32(d + t1); d<-c; c<-b; b<-a; a<-ow_u32(t1 + t2)
    }
    h <- ow_u32(h + c(a, b, c, d, e, f, g, hh))
  }
  as.raw(unlist(lapply(h, function(v) c(floor(v/16777216)%%256, floor(v/65536)%%256, floor(v/256)%%256, v%%256))))
}

omniwrap_verify_webhook_signature <- function(payload, secret, expected_hex) {
  if (!is.character(expected_hex) || length(expected_hex) != 1L || nchar(expected_hex) != 64L) return(FALSE)
  payload_raw <- if (is.raw(payload)) payload else charToRaw(enc2utf8(as.character(payload)))
  key_raw <- charToRaw(enc2utf8(as.character(secret)))
  if (length(key_raw) > 64L) key_raw <- ow_sha256_raw(key_raw)
  if (length(key_raw) < 64L) key_raw <- c(key_raw, raw(64L - length(key_raw)))
  ipad <- xor(key_raw, rep(as.raw(0x36), 64L))
  opad <- xor(key_raw, rep(as.raw(0x5c), 64L))
  mac <- ow_sha256_raw(c(opad, ow_sha256_raw(c(ipad, payload_raw))))
  computed <- paste(sprintf("%02x", as.integer(mac)), collapse = "")
  exp_bytes <- as.integer(charToRaw(tolower(expected_hex)))
  cmp_bytes <- as.integer(charToRaw(computed))
  if (length(exp_bytes) != length(cmp_bytes)) return(FALSE)
  diff <- 0L
  for (i in seq_along(cmp_bytes)) diff <- bitwOr(diff, bitwXor(cmp_bytes[i], exp_bytes[i]))
  identical(diff, 0L)
}

ow_escape <- function(value) {
  if (length(value) != 1L || !is.atomic(value) || is.na(value)) stop("Expected a single wire value")
  curl::curl_escape(enc2utf8(as.character(value)))
}

omniwrap_request <- function(client, method, path, body = NULL, path_values = list(), query = list()) {
  for (key in names(path_values)) {
    path <- gsub(paste0("{", key, "}"), ow_escape(path_values[[key]]), path, fixed = TRUE)
  }
  if (!startsWith(path, "/")) stop("Expected an absolute request path")
  if (!is.list(query) || (length(query) && (is.null(names(query)) || anyNA(names(query)) ||
      any(!nzchar(names(query)))))) stop("Expected a named list of query values")
  pairs <- unlist(lapply(seq_along(query), function(i) {
    values <- query[[i]]
    if (!length(values)) return(character())
    paste0(ow_escape(names(query)[i]), "=", vapply(values, ow_escape, character(1), USE.NAMES = FALSE))
  }), use.names = FALSE)
  url <- paste0(client$base_url, path)
  if (length(pairs)) url <- paste0(url, if (grepl("?", path, fixed = TRUE)) "&" else "?", paste(pairs, collapse = "&"))
  max_retries <- if (!is.null(client$max_retries)) as.integer(client$max_retries) else 0L
  can_retry <- method %in% c("GET", "HEAD", "OPTIONS", "PUT", "DELETE") ||
               (!is.null(client$idempotency_key) && nzchar(client$idempotency_key))
  max_attempts <- if (can_retry) max_retries + 1L else 1L
  refreshed_oauth <- FALSE
  attempt <- 1L
  repeat {
    handle <- curl::new_handle()
    headers <- c(Accept = "application/json")
    token <- client$bearer_token
    if ((is.null(token) || !nzchar(token)) && !is.null(client$oauth_provider)) {
      token <- omniwrap_oauth_access_token(client$oauth_provider, force_refresh = refreshed_oauth)
    }
    if (!is.null(token) && nzchar(token)) {
      headers["Authorization"] <- paste("Bearer", token)
    } else if (!is.null(client$basic_username) && nzchar(client$basic_username)) {
      pw <- if (is.null(client$basic_password)) "" else client$basic_password
      headers["Authorization"] <- paste("Basic", ow_base64(charToRaw(paste0(client$basic_username, ":", pw))))
    }
    if (!is.null(client$api_key) && nzchar(client$api_key)) {
      hdr <- if (!is.null(client$api_key_header) && nzchar(client$api_key_header)) client$api_key_header else "X-API-Key"
      headers[hdr] <- client$api_key
    }
    if (!is.null(client$idempotency_key) && nzchar(client$idempotency_key)) {
      headers["Idempotency-Key"] <- client$idempotency_key
    }
    if (!is.null(body)) {
      payload <- jsonlite::toJSON(body, auto_unbox = TRUE, null = "null", digits = NA)
      curl::handle_setopt(handle, postfields = charToRaw(enc2utf8(as.character(payload))))
      headers["Content-Type"] <- "application/json"
    } else if (method %in% c("POST", "PUT", "PATCH")) {
      # A body-less write still sends Content-Length: 0; some servers refuse it otherwise (411).
      curl::handle_setopt(handle, postfields = "")
      # An empty postfields makes libcurl add a form Content-Type; an empty value removes it.
      headers["Content-Type"] <- ""
    }
    curl::handle_setheaders(handle, .list = as.list(headers))
    conn_to <- if (!is.null(client$connect_timeout)) as.integer(client$connect_timeout) else 10L
    req_to <- if (!is.null(client$timeout)) as.integer(client$timeout) else 60L
    curl::handle_setopt(handle, customrequest = method, nobody = identical(method, "HEAD"),
                        followlocation = FALSE, connecttimeout = conn_to, timeout = req_to)
    if (!is.null(client$hooks) && is.function(client$hooks$before_request)) {
      client$hooks$before_request(method, url, attempt)
    }
    response <- tryCatch(curl::curl_fetch_memory(url, handle = handle), error = function(e) {
      if (!is.null(client$hooks) && is.function(client$hooks$on_error)) {
        client$hooks$on_error(method, url, e, attempt)
      }
      stop(e)
    })
    if (!is.null(client$hooks) && is.function(client$hooks$after_response)) {
      client$hooks$after_response(method, url, response$status_code, attempt)
    }
    if (identical(as.integer(response$status_code), 401L) && !refreshed_oauth && !is.null(client$oauth_provider)) {
      refreshed_oauth <- TRUE
      next
    }
    if (attempt < max_attempts && (as.integer(response$status_code) %in% c(408L, 429L) || as.integer(response$status_code) >= 500L)) {
      Sys.sleep(omniwrap_websocket_backoff_ms(attempt - 1L, 200, 5000) / 1000)
      attempt <- attempt + 1L
      next
    }
    return(list(status = response$status_code, method = method, url = url, body = response$content, headers = response$headers))
  }
}

get_user_context <- function(client) {
  omniwrap_request(client, "GET", "/v1/me/context", NULL, list(), list())
}

list_projects <- function(client, query = list()) {
  omniwrap_request(client, "GET", "/v1/projects", NULL, list(), query)
}

get_project <- function(client, `project_id`) {
  omniwrap_request(client, "GET", "/v1/projects/{projectId}", NULL, stats::setNames(list(`project_id`), c("projectId")), list())
}

